def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    opp = [h[1] for h in history]
    own = [h[0] for h in history]

    opp_def = opp.count('D')
    my_def = own.count('D')

    # Punish frequent defectors.
    if n >= 2 and opp_def >= 3 and opp_def * 2 >= n:
        return 'D'

    # Tit-for-two-tats: defect if opponent defected last two rounds.
    if n >= 2 and opp[-1] == 'D' and opp[-2] == 'D':
        return 'D'

    # Endgame: defect in the final two rounds.
    remaining = 100 - n
    if remaining <= 2:
        return 'D'

    # If both defected last round, continue defecting with 70% probability.
    if n >= 1 and own[-1] == 'D' and opp[-1] == 'D':
        if rng.random() < 0.7:
            return 'D'

    return 'C'
